package service
import("testing";"github.com/google/uuid";"github.com/onoja217/users-management-app/internal/models";"github.com/onoja217/users-management-app/internal/repository";"gorm.io/driver/sqlite";"gorm.io/gorm")
func TestNotificationPublishAndSchoolIsolation(t *testing.T){db,e:=gorm.Open(sqlite.Open("file:"+t.Name()+"?mode=memory&cache=shared"),&gorm.Config{});if e!=nil{t.Fatal(e)};if e=db.AutoMigrate(&models.School{},&models.User{},&models.Announcement{},&models.Notification{},&models.Student{},&models.StudentEnrollment{},&models.GuardianRelationship{});e!=nil{t.Fatal(e)};a:=models.School{Name:"School A",Code:"NA"};b:=models.School{Name:"School B",Code:"NB"};if e=db.Create(&a).Error;e!=nil{t.Fatal(e)};if e=db.Create(&b).Error;e!=nil{t.Fatal(e)};u:=models.User{Name:"Parent",Email:"np-"+uuid.NewString()+"@test",Role:"parent",Active:true,SchoolID:&a.ID};if e=db.Create(&u).Error;e!=nil{t.Fatal(e)};r:=repository.NewNotificationRepository(db);s:=NewNotificationService(r,db);x,e:=s.CreateAnnouncement(b.ID,models.Announcement{CreatedBy:u.ID,Title:"Wrong school",Body:"Hidden",Category:"fees",Audience:models.AudienceParents});if e!=nil{t.Fatal(e)};items,e:=s.ListAnnouncements(a.ID);if e!=nil||len(items)!=0{t.Fatalf("school A must not see B announcements: %d %v",len(items),e)};n,e:=s.Publish(b.ID,x.ID);if e!=nil||n!=1{t.Fatalf("publish: %d %v",n,e)};mine,e:=s.List(a.ID,u.ID);if e!=nil||len(mine)!=0{t.Fatalf("school A user must not receive B notification: %d %v",len(mine),e)};if e=s.MarkRead(a.ID,u.ID,mineID(mine));e!=nil&&len(mine)>0{t.Fatal(e)}}
func mineID(v []models.Notification)uuid.UUID{if len(v)==0{return uuid.Nil};return v[0].ID}
